window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c864068600bda911"]={"versions": [{"id": "FIG-c864068600bda911", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendefinition im Kontext des AUTOSAR Diagnostic Communication Managers (DCM). Das Diagramm spezifiziert ein Service-Interface für OBD-Dienste (<code>InfoTypeServices</code>) innerhalb eines Diagrammrahmens <code>class InfoTypeServices</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Interface <code>«interface» InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> mit parametrisiertem Bezeichner.</p>\n<p class=\"fig-p\">Enthaltene Operation:</p>\n<ul class=\"fig-list\">\n<li><code>GetInfoTypeValue(return :Std_ReturnType, DataValueBuffer :uint8*)</code></li>\n<li>Rückgabetyp: <code>Std_ReturnType</code></li>\n<li>Parameter: <code>DataValueBuffer :uint8*</code> (Zeiger auf Puffer zur Aufnahme der InfoType-Werte)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone Funktionssignatur bzw. Client-Server-Interface-Operation. Der Aufrufer (DCM) übergibt einen Pufferzeiger (<code>DataValueBuffer</code>), in den der Service-Provider die fahrzeugspezifischen Diagnosedaten des entsprechenden InfoTypes schreibt und das Ergebnis via <code>Std_ReturnType</code> signalisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellenspezifikation für die Bereitstellung von OBD-InfoTypes (Dienst 0x09) im DCM. Der Platzhalter <code>&lt;INFOTYPENUMBER&gt;</code> ist gemäß der jeweiligen unterstützten InfoType-Nummer zu instanziieren. Implementierende Software-Komponenten müssen die Operation mit identischer Signatur und Parametertypen bereitstellen.</p>"}, {"id": "FIG-dffaaad9bfc91f22", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Schnittstellendefinition im Kontext des AUTOSAR Diagnostic Communication Managers (DCM). Das Diagramm stellt die Interface-Klasse <code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> als freistehendes Modellelement ohne umgebenden Diagrammrahmen dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Interface <code>«interface» InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> mit parametrisiertem Bezeichner.</p>\n<p class=\"fig-p\">Enthaltene Operation:</p>\n<ul class=\"fig-list\">\n<li><code>GetInfoTypeValue(return :Std_ReturnType, DataValueBuffer :uint8*)</code></li>\n<li>Rückgabetyp: <code>Std_ReturnType</code></li>\n<li>Parameter: <code>DataValueBuffer :uint8*</code> (Zeiger auf Puffer zur Aufnahme der InfoType-Werte)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Synchrone Funktionssignatur bzw. Client-Server-Interface-Operation. Der Aufrufer (DCM) übergibt einen Pufferzeiger (<code>DataValueBuffer</code>), in den der Service-Provider die fahrzeugspezifischen Diagnosedaten des entsprechenden InfoTypes schreibt und das Ergebnis via <code>Std_ReturnType</code> signalisiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Schnittstellenspezifikation für die Bereitstellung von OBD-InfoTypes (Dienst 0x09) im DCM. Der Platzhalter <code>&lt;INFOTYPENUMBER&gt;</code> ist gemäß der jeweiligen unterstützten InfoType-Nummer zu instanziieren. Implementierende Software-Komponenten müssen die Operation mit identischer Signatur und Parametertypen bereitstellen.</p>"}], "trans": [{"from": "FIG-c864068600bda911", "to": "FIG-dffaaad9bfc91f22", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Äußerer Klassendiagramm-Rahmen (<code>class InfoTypeServices</code>) entfernt; das Interface <code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> steht nun freistehend ohne umgebenden Rahmen.</li>\n<li>Interface-Name <code>InfoTypeServices_&lt;INFOTYPENUMBER&gt;</code> von kursiver Schriftart auf aufrechte Schriftart geändert.</li>\n<li>Artefakt aus dem Dokument-Fließtext am oberen linken Rand (<code>Dcm423).</code>) entfernt.</li>\n</ul>"}]};
